// GENERATED FILE. Do not edit by hand.
// Regenerate with:  python3 scripts/fetch_terrain.py
//
// Terrain for the SignalLab map view. Elevation comes from the AWS Terrain
// Tiles open dataset (Terrarium encoding), which over the continental US is
// derived from USGS 3DEP/NED. Each grid was spot-checked against USGS ned10m
// before being written; the agreement is recorded per site below.
//
// The matching orthoimagery is USGS National Map (public domain), resampled
// through the same projection onto the same window at 2.93 m per pixel,
// so the contours land exactly where the imagery says they should. The files
// live in static/img/terrain/ and are fetched by the browser, not bundled.
//
// Two grids per site, because SSR and accuracy want different things:
//
//   * the inlined one below, 200x200 at 30.2 m per sample, is what the
//     bundle carries, so it renders on the server and on the first frame.
//   * `fine` names a 512x512 file (11.7 m per sample, i.e. 3DEP's own
//     resolution) under static/. The browser fetches it once, and installFine()
//     swaps it in underneath a model that never learns it happened.
//
// Heights are int16 decimetres above `base`, row-major, row 0 = north edge,
// column 0 = west edge, over a 6 km square. Both grids share one `base`.

export const GRID = 200;
export const FINE_GRID = 512;
export const SPAN_M = 6000;
export const STEP_M = SPAN_M / (GRID - 1);

export const SITES = [
  {
    id: "mdrs",
    name: "Mars Desert Research Station",
    sub: "Hanksville, Utah, where URC runs",
    lat: 38.40639, lon: -110.79194,
    base: 1329.0, min: 1329.9, max: 1538.3,
    // agreement with USGS ned10m: mean 2.55 m, worst 9.38 m
    image: "img/terrain/mdrs.webp", // 442 KB
    fine: "data/terrain/mdrs.bin", // 512 KB, 512x512 int16
    data: "",
  },
  {
    id: "rolla",
    name: "Rolla test site",
    sub: "Missouri S&T, the home field",
    lat: 37.95003, lon: -91.783062,
    base: 256.0, min: 256.7, max: 369.7,
    // agreement with USGS ned10m: mean 0.88 m, worst 4.53 m
    image: "img/terrain/rolla.webp", // 1288 KB
    fine: "data/terrain/rolla.bin", // 512 KB, 512x512 int16
    data: "",
  },
  {
    id: "tucumcari",
    name: "Tucumcari Mountain",
    sub: "New Mexico, the mesa the autonomy LiDAR covers",
    lat: 35.16037, lon: -103.703198,
    base: 1222.0, min: 1222.1, max: 1509.5,
    // agreement with USGS ned10m: mean 0.16 m, worst 0.78 m
    image: "img/terrain/tucumcari.webp", // 977 KB
    fine: "data/terrain/tucumcari.bin", // 512 KB, 512x512 int16
    data: "",
  },
];

// Every grid carries the side length it was sampled at, so a consumer never
// has to know which of the two it is holding, and swapping one for the other
// cannot silently reinterpret the rows.
const tag = (arr, n) => {
  arr.n = n;
  return arr;
};

// Base64 -> Int16Array, decoded once on first use. Works in Node (SSR) and in
// the browser without touching any DOM API.
const decoded = new Map();

export function heightGrid(id) {
  if (decoded.has(id)) return decoded.get(id);
  const site = SITES.find((s) => s.id === id) || SITES[0];
  const bin =
    typeof atob === 'function'
      ? atob(site.data)
      : Buffer.from(site.data, 'base64').toString('binary');
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const dm = new Int16Array(bytes.buffer);
  const out = new Float32Array(dm.length);
  for (let i = 0; i < dm.length; i++) out[i] = site.base + dm[i] / 10;
  decoded.set(id, tag(out, GRID));
  return decoded.get(id);
}

// Replace a site's grid with the fine one, given the raw int16 file. Returns
// false rather than throwing on a short or truncated read, because a half a
// heightmap is worse than the coarse one we already have.
export function installFine(id, buffer) {
  const site = SITES.find((s) => s.id === id);
  if (!site) return false;
  const want = FINE_GRID * FINE_GRID;
  if (buffer.byteLength !== want * 2) return false;
  const dm = new Int16Array(buffer);
  const out = new Float32Array(want);
  for (let i = 0; i < want; i++) out[i] = site.base + dm[i] / 10;
  decoded.set(id, tag(out, FINE_GRID));
  return true;
}

export const gridIsFine = (id) => (decoded.get(id) || {}).n === FINE_GRID;
